CREATE OR REPLACE FUNCTION public.rh_public_open(p_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l rh_links%ROWTYPE; d jsonb; BEGIN SELECT * INTO l FROM rh_links WHERE code=p_code FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('found',false); END IF; IF l.estado='enviado' THEN RETURN jsonb_build_object('found',true,'submitted',true,'username',l.instagram_username); END IF; IF l.estado='gerado' THEN UPDATE rh_links SET estado='aberto',opened_at=now() WHERE id=l.id; END IF; INSERT INTO rh_candidatos(link_id,vaga_id,instagram_username) VALUES(l.id,l.vaga_id,l.instagram_username) ON CONFLICT(link_id) DO NOTHING; SELECT rascunho INTO d FROM rh_candidatos WHERE link_id=l.id; RETURN jsonb_build_object('found',true,'submitted',false,'username',l.instagram_username,'draft',d,'vaga',(SELECT jsonb_build_object('titulo',titulo,'resumo',resumo) FROM rh_vagas WHERE id=l.vaga_id),'guia',(SELECT guia_atendimento FROM rh_settings WHERE id=1),'cenarios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'contexto',contexto,'mensagem',mensagem_cliente) ORDER BY ordem) FROM rh_cenarios WHERE vaga_id=l.vaga_id AND ativo),'[]')); END $$; REVOKE ALL ON FUNCTION public.rh_public_open(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.rh_public_open(text) TO service_role;